#!/usr/bin/env bash
# Sets up absmart/iac-pipeline-test for the infrastructure pipeline. Generated by IaC Pipeline Planner.
#
# Run it after scripts/setup-azure.sh, with the GitHub CLI signed in as a repository
# admin (gh auth login). Needs gh and jq. It sets the repository variables; creates per
# environment a deployment environment with its reviewers and an <env>-plan environment
# for its plans, each allowing only the branches or tags it deploys from; and adds a
# ruleset per deploying branch (pull requests, approvals, checks) and tag pattern.

set -euo pipefail
# Git Bash: keep /subscriptions/... arguments as they are.
export MSYS_NO_PATHCONV=1

REPO='absmart/iac-pipeline-test'
VALUES_FILE="${VALUES_FILE:-pipeline-values.env}"
[ -f "$VALUES_FILE" ] || { echo "Run scripts/setup-azure.sh first: $VALUES_FILE is missing." >&2; exit 1; }
set -a
# shellcheck disable=SC1090
. "$VALUES_FILE"
set +a

echo "Setting the repository variables..."
while IFS='=' read -r name value; do
  case "$name" in AZURE_*) gh variable set "$name" --body "$value" --repo "$REPO" ;; esac
done < "$VALUES_FILE"

# reviewer <login or org/team>: the reviewer as the environments API wants it.
reviewer() {
  if [[ "$1" == */* ]]; then
    jq -n --argjson id "$(gh api "orgs/${1%%/*}/teams/${1#*/}" --jq .id)" '{type: "Team", id: $id}'
  else
    jq -n --argjson id "$(gh api "users/$1" --jq .id)" '{type: "User", id: $id}'
  fi
}

# ensure_environment <name> <wait minutes> <policies: type:pattern,...> <reviewer>...
ensure_environment() {
  local name="$1" wait="$2" reviewers="[]" self=false existing p
  local -a wanted
  IFS=, read -ra wanted <<< "$3"
  shift 3
  for r in "$@"; do reviewers="$(jq -c --argjson r "$(reviewer "$r")" '. + [$r]' <<< "$reviewers")"; done
  [ "$reviewers" = "[]" ] || self=false
  jq -n --argjson wait "$wait" --argjson reviewers "$reviewers" --argjson self "$self" \
    '{wait_timer: $wait, prevent_self_review: $self, reviewers: $reviewers,
      deployment_branch_policy: {protected_branches: false, custom_branch_policies: true}}' |
    gh api -X PUT "repos/$REPO/environments/$name" --input - > /dev/null
  existing="$(gh api "repos/$REPO/environments/$name/deployment-branch-policies" --jq '.branch_policies[] | "\(.type // "branch"):\(.name)"')"
  for p in "${wanted[@]}"; do
    grep -qxF "$p" <<< "$existing" ||
      gh api -X POST "repos/$REPO/environments/$name/deployment-branch-policies" -f name="${p#*:}" -f type="${p%%:*}" > /dev/null
  done
}

# ensure_ruleset <JSON>: creates the ruleset, or updates the one with its name.
ensure_ruleset() {
  local id
  id="$(gh api "repos/$REPO/rulesets?includes_parents=false" --jq ".[] | select(.name == $(jq '.name' <<< "$1")) | .id")"
  if [ -n "$id" ]; then
    gh api -X PUT "repos/$REPO/rulesets/$id" --input - <<< "$1" > /dev/null
  else
    gh api -X POST "repos/$REPO/rulesets" --input - <<< "$1" > /dev/null
  fi
}

echo "Environment dev..."
ensure_environment 'dev' 0 'branch:main'
ensure_environment 'dev-plan' 0 'branch:main'
echo "Environment prd..."
ensure_environment 'prd' 0 'branch:main' 'absmart'
ensure_environment 'prd-plan' 0 'branch:main'

echo "Ruleset for the branch main..."
ensure_ruleset '{"name":"e2e branch main","target":"branch","enforcement":"active","conditions":{"ref_name":{"include":["refs/heads/main"],"exclude":[]}},"rules":[{"type":"deletion"},{"type":"non_fast_forward"},{"type":"pull_request","parameters":{"required_approving_review_count":0,"dismiss_stale_reviews_on_push":true,"require_code_owner_review":false,"require_last_push_approval":false,"required_review_thread_resolution":false}},{"type":"required_status_checks","parameters":{"strict_required_status_checks_policy":false,"required_status_checks":[{"context":"validate","integration_id":15368},{"context":"plan (dev)","integration_id":15368},{"context":"plan (prd)","integration_id":15368}]}}]}'

echo "Done."
